// RENOVO CRETE V10.1 — compléments ciblés
const RC101_ORDER_STATUSES=['En cours de vérification','Modification demandée par le client','Prête à être récupérée','Validée / récupérée','Refusée','Annulée'];
const RC101_PAYMENT_STATUSES=['Non payé / en attente de paiement','Payé','Remboursé'];
const RC101_ADMIN_TABS=[['admin-dashboard','⌂','Accueil'],['clients','👥','Professionnels et partenaires'],['global-orders','◫','Commandes globales'],['receivables','€','Impayés & échéances'],['portfolio','◆','Portefeuille client'],['loyalty','★','Fidélité & catégories'],['referrals','↗','Parrainage'],['system-library','▧','Bibliothèque des systèmes'],['admin-messages','✉','Messagerie professionnelle'],['admin-catalog','▥','Catalogue & tarifs'],['admin-import','⇅','Imports / exports'],['admin-audit','≡','Journal d’audit'],['admin-users','♟','Administrateurs'],['admin-settings','⚙','Paramètres'],['faq','?','FAQ']];
const RC101_CLIENT_TABS=[['dashboard','⌂','Accueil'],['calculator','▦','Calculateur par système'],['visualizer','◈','Visualiseur du sol'],['cart','🛒','Commande produits'],['simulations','▤','Mes simulations enregistrées'],['orders','◫','Mes commandes'],['catalog','▥','Catalogue'],['support','✉','Service client'],['faq','?','Questions fréquentes']];
const RC101_SYSTEM_IMAGES={'dss-742':'assets/hermetic-stout-double.png','uc-neat':'assets/hermetic-urethane-cement.png','uc-flake':'assets/hermetic-urethane-cement.png','uc-quartz':'assets/hermetic-urethane-cement.png','uc-stout':'assets/hermetic-urethane-cement.png','sqs-367':'assets/hermetic-quartz-single.png'};
let rc101MessageMode='active',rc101AdditionalResults=[];

function rc101ExactOrderStatus(value){const v=String(value||'').trim();if(RC101_ORDER_STATUSES.includes(v))return v;if(v==='Modification demandée par le client')return v;if(['Prête à être récupérée','En préparation'].includes(v))return'Prête à être récupérée';if(['Validée / récupérée','Récupérée','Terminée','Expédiée / livrée','Confirmée'].includes(v))return'Validée / récupérée';if(v==='Refusée')return v;if(['Annulée','Remboursée intégralement'].includes(v))return'Annulée';return'En cours de vérification'}
function rc101ExactPaymentStatus(value){const v=String(value||'').trim();if(v==='Payé')return'Payé';if(['Remboursé','Partiellement remboursé','Remboursement en cours'].includes(v))return'Remboursé';return'Non payé / en attente de paiement'}
function rc101ApplyExactStatuses(){RC_ORDER_STATUSES.splice(0,RC_ORDER_STATUSES.length,...RC101_ORDER_STATUSES);RC_PAYMENT_STATUSES.splice(0,RC_PAYMENT_STATUSES.length,...RC101_PAYMENT_STATUSES);ORDER_STATUSES_V96.splice(0,ORDER_STATUSES_V96.length,...RC101_ORDER_STATUSES);PAYMENT_STATUSES_V96.splice(0,PAYMENT_STATUSES_V96.length,...RC101_PAYMENT_STATUSES);for(const{order:o}of rcAllOrders()){o.status=rc101ExactOrderStatus(o.status);o.paymentStatus=rc101ExactPaymentStatus(o.paymentStatus)}}
normalizeOrderStatusV96=rc101ExactOrderStatus;normalizePaymentStatusV96=rc101ExactPaymentStatus;
orderStatusClassV96=v=>({'En cours de vérification':'st-review','Modification demandée par le client':'st-change','Prête à être récupérée':'st-ready','Validée / récupérée':'st-complete','Refusée':'st-refused','Annulée':'st-cancelled'})[rc101ExactOrderStatus(v)]||'st-review';
paymentStatusClassV96=v=>rc101ExactPaymentStatus(v)==='Payé'?'pay-paid':rc101ExactPaymentStatus(v)==='Remboursé'?'pay-refunded':'pay-waiting';
rcStatusClass=v=>rc101ExactOrderStatus(v)==='Validée / récupérée'?'ok':['Refusée','Annulée'].includes(rc101ExactOrderStatus(v))?'danger':'warn';
rcPaymentClass=v=>rc101ExactPaymentStatus(v)==='Payé'?'ok':rc101ExactPaymentStatus(v)==='Remboursé'?'warn':'danger';

function rc101Settings(){store.settings=store.settings||{};store.settings.navConfig=store.settings.navConfig||{adminOrder:[],adminHidden:[],clientOrder:[],clientHidden:[]};store.settings.systemLibrary=store.settings.systemLibrary||{};if(!Number.isFinite(Number(store.settings.maxCalculatorSystems)))store.settings.maxCalculatorSystems=10;return store.settings}
function rc101SystemMeta(id){const settings=rc101Settings(),sys=SYSTEMS.find(s=>s.id===id);settings.systemLibrary[id]=settings.systemLibrary[id]||{image:RC101_SYSTEM_IMAGES[id]||'',layers:(sys?.layers||[]).map(x=>x.name)};return settings.systemLibrary[id]}
function rc101SystemImage(id){return rc101SystemMeta(id).image||RC101_SYSTEM_IMAGES[id]||''}
function rc101SystemImageHTML(id,title=''){const img=rc101SystemImage(id),sys=SYSTEMS.find(s=>s.id===id),layers=rc101SystemMeta(id).layers||sys?.layers?.map(x=>x.name)||[];return img?`<img class="rc101-system-image" src="${esc(img)}" alt="Couches du système ${esc(title||sys?.name||'')}">`:`<div class="rc101-system-placeholder"><div><b>Schéma des couches — ${esc(title||sys?.name||'Système')}</b><ol>${layers.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div></div>`}
function rc101ApplySystemLayers(){for(const sys of SYSTEMS){const meta=rc101SystemMeta(sys.id);if(!Array.isArray(meta.layers)||!meta.layers.length)meta.layers=sys.layers.map(x=>x.name);const old=sys.layers.slice();sys.layers=meta.layers.map((name,i)=>{const prior=old[i]||old.find(x=>x.name===name);return prior?{...prior,name}:{id:'admin-step-'+i+'-'+sys.id,name,category:'custom-step',defaultProduct:null,allowedProducts:[],mode:'usage',rate:null,rateUnit:'unité',depends:null,adminNote:'Étape ajoutée depuis la bibliothèque.'}})}}
function rc101Migrate(){rc101Settings();for(const c of rcAllClients()){c.address=c.address||'';c.businessActivity=c.businessActivity||'';c.phone=c.phone||'';c.expertiseLevel=c.expertiseLevel||'Débutant';c.category=c.category||'Professionnel';if(typeof c.catalogAccess!=='boolean')c.catalogAccess=false;if(typeof c.visualizerEnabled!=='boolean')c.visualizerEnabled=false}for(const sys of SYSTEMS)rc101SystemMeta(sys.id);rc101ApplySystemLayers();rc101ApplyExactStatuses();saveStore()}
const rc101BaseMigrateV10=rcMigrateV10;rcMigrateV10=function(){rc101BaseMigrateV10();rc101ApplyExactStatuses();saveStore()};
function rc101OrderedTabs(kind){const cfg=rc101Settings().navConfig,base=kind==='admin'?RC101_ADMIN_TABS:RC101_CLIENT_TABS,key=kind==='admin'?'adminOrder':'clientOrder',hiddenKey=kind==='admin'?'adminHidden':'clientHidden',byId=Object.fromEntries(base.map(x=>[x[0],x])),order=[...(cfg[key]||[]),...base.map(x=>x[0]).filter(id=>!(cfg[key]||[]).includes(id))];return order.filter(id=>byId[id]&&!cfg[hiddenKey].includes(id)).map(id=>byId[id])}
adminNav=()=>rc101OrderedTabs('admin');
clientNav=()=>rc101OrderedTabs('client').filter(([v])=>v!=='catalog'||currentClient()?.catalogAccess).filter(([v])=>v!=='visualizer'||visualizerAllowedV95());

function rc101MonthData(rows){const months=[];for(let i=5;i>=0;i--){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);months.push({key:d.getFullYear()+'-'+d.getMonth(),label:d.toLocaleDateString('fr-FR',{month:'short'}).replace('.',''),count:0,total:0})}for(const x of rows){const d=new Date(x.order.createdAt),m=months.find(y=>y.key===d.getFullYear()+'-'+d.getMonth());if(m){m.count++;m.total+=Number(x.order.totalEUR||0)}}return months}
function rc101Bars(months){const max=Math.max(1,...months.map(x=>x.count));return`<div class="rc101-bars">${months.map(x=>`<div class="rc101-bar"><b>${x.count}</b><i style="height:${Math.max(5,x.count/max*135)}px"></i><small>${esc(x.label)}</small></div>`).join('')}</div>`}
renderAdminDashboard=function(){const clients=rcAllClients(),rows=rcAllOrders().sort((a,b)=>new Date(b.order.createdAt)-new Date(a.order.createdAt)),months=rc101MonthData(rows),paid=rows.reduce((n,x)=>n+rcOrderPaid(x.order),0),balance=rows.reduce((n,x)=>n+rcOrderBalance(x.order),0),tiers={Standard:0,Premium:0,Prestige:0};clients.forEach(c=>tiers[rcTierFor(rcClientStats(c).net)]++);const totalClients=Math.max(1,clients.length),a=tiers.Standard/totalClients*100,b=(tiers.Standard+tiers.Premium)/totalClients*100,statuses=RC101_ORDER_STATUSES.map(s=>({s,n:rows.filter(x=>x.order.status===s).length})),maxStatus=Math.max(1,...statuses.map(x=>x.n)),systems={};rows.forEach(x=>{const k=rcSystemKey(x.order);systems[k]=(systems[k]||0)+Number(x.order.totalEUR||0)});const top=Object.entries(systems).sort((a,b)=>b[1]-a[1]).slice(0,5),maxSystem=Math.max(1,...top.map(x=>x[1]));return`<div class="rc-v10-hero"><h2>Pilotage RENOVO CRETE</h2><p>Vue centrale des clients, commandes, paiements et performances commerciales.</p><div class="rc-v10-actions"><button class="btn primary" onclick="go('global-orders')">Traiter les commandes</button><button class="btn secondary" onclick="go('clients')">Ouvrir le CRM client</button></div></div><div class="rc-v10-kpis">${rcKpi('Professionnels actifs',clients.filter(c=>c.active).length,`${clients.length} comptes`,'clients')}${rcKpi('Commandes à vérifier',rows.filter(x=>x.order.status==='En cours de vérification').length,'Action administrative','global-orders')}${rcKpi('Reste à encaisser',rcMoney(balance),'Paiements à suivre','receivables')}${rcKpi('CA encaissé',rcMoney(paid),'Paiements enregistrés','portfolio')}${rcKpi('Messages non lus',unreadAdminMessagesV92(),'Accéder aux échanges','admin-messages')}${rcKpi('Systèmes disponibles',SYSTEMS.length,'Bibliothèque complète','system-library')}</div><div class="rc101-chart-grid"><section class="rc-v10-panel rc101-chart" onclick="go('global-orders')"><span class="eyebrow">ACTIVITÉ</span><h3>Commandes sur 6 mois</h3>${rc101Bars(months)}</section><section class="rc-v10-panel rc101-chart" onclick="go('portfolio')"><span class="eyebrow">RÉPARTITION</span><h3>État du portefeuille</h3><div class="rc101-donut-layout"><div class="rc101-donut" style="--a:${a}%;--b:${b}%" data-total="${clients.length}"></div><div class="rc101-legend">${Object.entries(tiers).map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('')}</div></div></section><section class="rc-v10-panel rc101-chart" onclick="go('global-orders')"><span class="eyebrow">TRAITEMENT</span><h3>Commandes par statut</h3><div class="rc101-status-bars">${statuses.map(x=>`<div class="rc101-status-row"><span>${esc(x.s)}</span><i style="width:${Math.max(3,x.n/maxStatus*100)}%"></i><b>${x.n}</b></div>`).join('')}</div></section><section class="rc-v10-panel rc101-chart" onclick="go('portfolio')"><span class="eyebrow">VENTES PRODUITS</span><h3>Valeur par système</h3><div class="rc101-status-bars">${top.map(x=>`<div class="rc101-status-row"><span>${esc(x[0])}</span><i style="width:${Math.max(3,x[1]/maxSystem*100)}%"></i><b>${Math.round(x[1]/1000)}k</b></div>`).join('')||'<div class="rc-v10-empty">Aucune vente enregistrée.</div>'}</div></section></div><div class="rc101-chart-grid"><section class="rc-v10-panel"><h3>Dernières commandes</h3><div class="rc-v10-mini-list">${rows.slice(0,6).map(x=>`<div class="rc101-recent" data-rc101-order="${x.tenantId}|${x.index}"><span><b>${esc(x.order.id)}</b><br><small>${esc(x.client.company)} · ${esc(rcSystemKey(x.order))}</small></span><span><b>${rcMoney(x.order.totalEUR)}</b><br><small>${esc(x.order.status)}</small></span></div>`).join('')||'<div class="rc-v10-empty">Aucune commande.</div>'}</div></section><section class="rc-v10-panel"><h3>Lecture financière</h3><div class="rc-v10-mini-list"><div><span>Montant encaissé</span><b>${rcMoney(paid)}</b></div><div><span>Solde restant</span><b class="rc-v10-danger">${rcMoney(balance)}</b></div><div><span>Clients débiteurs</span><b>${clients.filter(c=>rcClientStats(c).balance>0).length}</b></div></div></section></div>`};

function rc101ClientDataset(c){const s=rcClientStats(c),systems=[...new Set(s.orders.map(rcSystemKey))];return{tier:rcTierFor(s.net),search:(c.company+' '+rcClientName(c)+' '+c.email+' '+c.phone+' '+c.siret+' '+c.businessActivity).toLowerCase(),systems:systems.join('|').toLowerCase(),amount:s.net}}
rcClientCard=function(c){const s=rcClientStats(c),d=rc101ClientDataset(c),next=rcNextTier(s.net),progress=Math.min(100,next.target?s.net/next.target*100:100);return`<article class="rc-v10-client" data-rc-client data-search="${esc(d.search)}" data-tier="${d.tier}" data-debt="${s.balance>0?'yes':'no'}" data-expertise="${esc(c.expertiseLevel||'Débutant')}" data-price-tier="${esc(c.priceTier||'recommended')}" data-catalog="${c.catalogAccess?'yes':'no'}" data-systems="${esc(d.systems)}" data-amount="${d.amount}"><div style="display:flex;justify-content:space-between;gap:8px"><div><h3>${esc(c.company||'Sans société')}</h3><small>${esc(rcClientName(c))}</small></div><span class="rc-v10-tier">${d.tier}</span></div><p>${esc(c.businessActivity||'Activité non renseignée')}<br>${esc(c.email||'E-mail non renseigné')} · ${esc(c.phone||'Téléphone non renseigné')}</p><div class="rc-v10-mini-list"><div><span>Total achats</span><b>${rcMoney(s.net)}</b></div><div><span>Encaissé</span><b>${rcMoney(s.paid)}</b></div><div><span>Solde dû</span><b class="${s.balance?'rc-v10-danger':''}">${rcMoney(s.balance)}</b></div></div><div class="rc-v10-progress"><span style="width:${progress}%"></span></div><small>${next.remaining?`${rcMoney(next.remaining)} avant ${next.label}`:'Palier Prestige atteint'}</small><div class="toolbar"><button class="btn primary small" data-rc-client-sheet="${c.id}">Voir / modifier la fiche</button><button class="btn secondary small" data-open-client="${c.id}">Ouvrir l’espace</button></div></article>`};
renderClients=function(){const cs=rcAllClients(),levels=[...new Set(cs.map(c=>c.expertiseLevel||'Débutant'))].sort();return`<div class="rc-v10-hero"><h2>Professionnels et partenaires</h2><p>Gérez les profils, niveaux, tarifs et droits d’accès depuis une fiche client complète.</p><div class="rc-v10-actions"><button class="btn primary" id="newClient">Nouveau professionnel</button></div></div><div class="rc101-filter"><div class="field"><label>Nom / société</label><input id="rcClientSearch" placeholder="Rechercher…"></div><div class="field"><label>Niveau</label><select id="rcClientExpertise"><option value="">Tous les niveaux</option>${levels.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Tarif</label><select id="rcClientPrice"><option value="">Tous les tarifs</option><option value="recommended">Tarif de référence</option><option value="large">Tarif grand chantier</option><option value="premium">Tarif premium</option></select></div><div class="field"><label>Catalogue</label><select id="rcClientCatalog"><option value="">Tous</option><option value="yes">Accès autorisé</option><option value="no">Accès non autorisé</option></select></div><div class="field"><label>Catégorie fidélité</label><select id="rcClientTier"><option value="">Toutes</option><option>Standard</option><option>Premium</option><option>Prestige</option></select></div><div class="field"><label>Solde</label><select id="rcClientDebt"><option value="">Tous</option><option value="yes">Solde dû</option><option value="no">À jour</option></select></div></div><div class="rc-v10-client-grid">${cs.map(rcClientCard).join('')||'<div class="rc-v10-empty">Aucun client.</div>'}</div>`};
rcClientSheet=function(id){const c=store.accounts.find(a=>a.id===id);if(!c)return;const s=rcClientStats(c),tier=rcTierFor(s.net),t=store.tenants[id]||{};showModal(`<div class="rc101-client-sheet"><div style="display:flex;justify-content:space-between;gap:10px"><div><h3>Fiche client — ${esc(c.company)}</h3><p>${esc(rcClientName(c))}</p></div><span class="rc-v10-tier">${tier}</span></div><div class="rc101-form-grid"><div class="field"><label>Nom / raison sociale</label><input id="rc101Company" value="${esc(c.company||'')}"></div><div class="field"><label>Activité de l’entreprise / client</label><input id="rc101Activity" value="${esc(c.businessActivity||'')}"></div><div class="field"><label>Adresse postale</label><input id="rc101Address" value="${esc(c.address||'')}"></div><div class="field"><label>Téléphone</label><input id="rc101Phone" value="${esc(c.phone||'')}"></div><div class="field"><label>E-mail</label><input id="rc101Email" type="email" value="${esc(c.email||'')}"></div><div class="field"><label>SIRET</label><input id="rc101Siret" value="${esc(c.siret||'')}"></div><div class="field"><label>Tarif</label><select id="rc101PriceTier"><option value="recommended" ${c.priceTier==='recommended'?'selected':''}>Tarif de référence</option><option value="large" ${c.priceTier==='large'?'selected':''}>Tarif grand chantier</option><option value="premium" ${c.priceTier==='premium'?'selected':''}>Tarif premium</option></select></div><div class="field"><label>Perte spécifique %</label><input id="rc101Waste" type="number" min="0" max="100" step=".1" value="${c.userWastePct??''}"></div><div class="field"><label>Niveau d’expertise</label><select id="rc101Expertise">${expertiseOptionsV92(c.expertiseLevel||'Débutant')}</select></div><div class="field"><label>Catégorie</label><select id="rc101Category">${categoryOptionsV91(c.category)}</select></div></div><div class="rc101-permissions" style="margin-top:12px"><label class="rc101-permission"><span><b>Accès au catalogue</b><small>Autoriser les prix et produits disponibles</small></span><input id="rc101Catalog" type="checkbox" ${c.catalogAccess?'checked':''}></label><label class="rc101-permission"><span><b>Accès au visualiseur</b><small>Fonction expérimentale, désactivée par défaut</small></span><input id="rc101Visualizer" type="checkbox" ${c.visualizerEnabled?'checked':''}></label></div><div class="rc-v10-kpis" style="margin-top:12px">${rcKpi('Commandes',s.orders.length,rcMoney(s.net),'global-orders')}${rcKpi('Messages',(t.messages||[]).filter(m=>!m.deletedByAdmin).length,'Échanges actifs','admin-messages')}${rcKpi('Encaissé',rcMoney(s.paid),'Paiements','receivables')}${rcKpi('Solde',rcMoney(s.balance),'Reste dû','receivables')}</div><div class="toolbar"><button class="btn secondary" id="rc101ClientOrders">Voir ses commandes</button><button class="btn secondary" id="rc101ClientMessages">Voir ses messages</button><button class="btn secondary" onclick="closeModal()">Annuler</button><button class="btn primary" id="rc101SaveClient">Enregistrer la fiche</button></div></div>`);$('rc101SaveClient').onclick=()=>{const old={company:c.company,address:c.address,activity:c.businessActivity};c.company=$('rc101Company').value.trim()||c.company;c.businessActivity=$('rc101Activity').value.trim();c.address=$('rc101Address').value.trim();c.phone=$('rc101Phone').value.trim();c.email=$('rc101Email').value.trim();c.siret=$('rc101Siret').value.trim();c.priceTier=$('rc101PriceTier').value;c.userWastePct=$('rc101Waste').value===''?null:Number($('rc101Waste').value);c.expertiseLevel=$('rc101Expertise').value;c.category=$('rc101Category').value;c.catalogAccess=$('rc101Catalog').checked;c.visualizerEnabled=$('rc101Visualizer').checked;auditV9('Mise à jour fiche client','utilisateur:'+id,old,{company:c.company,address:c.address,activity:c.businessActivity});saveStore();closeModal();renderShell();toast('Fiche client enregistrée.')};$('rc101ClientOrders').onclick=()=>{closeModal();currentView='global-orders';renderShell();setTimeout(()=>{if($('rcOrderSearch')){$('rcOrderSearch').value=c.company;rcRefreshOrders()}},0)};$('rc101ClientMessages').onclick=()=>{adminMessageClientIdV91=id;closeModal();go('admin-messages')}};

function rc101OrderSystems(o){return[...new Set((o.items||[]).map(i=>i.systemName).filter(Boolean).concat(o.systemName||[]))]}
function rc101PeriodBounds(period,start,end){let a=-Infinity,b=Infinity,now=Date.now();if(period==='today'){const d=new Date();d.setHours(0,0,0,0);a=d.getTime();b=a+86400000-1}else if(period==='d30')a=now-30*86400000;else if(period==='m6')a=now-183*86400000;else if(period==='y1')a=now-365*86400000;else if(period==='custom'){if(start)a=new Date(start+'T00:00:00').getTime();if(end)b=new Date(end+'T23:59:59').getTime()}return[a,b]}
function renderPortfolioV10(){const clients=rcAllClients().map(c=>({c,s:rcClientStats(c)})).sort((a,b)=>b.s.net-a.s.net),systems=[...new Set(rcAllOrders().flatMap(x=>rc101OrderSystems(x.order)))].sort();return`<div class="rc-v10-hero"><h2>Portefeuille client</h2><p>Filtrez automatiquement par client inscrit, système, période et montant.</p></div><div class="rc101-filter"><div class="field"><label>Client</label><select id="rc101PortfolioClient"><option value="">Tous les clients</option>${clients.map(x=>`<option value="${x.c.id}">${esc(x.c.company)} — ${esc(rcClientName(x.c))}</option>`).join('')}</select></div><div class="field"><label>Système</label><select id="rc101PortfolioSystem"><option value="">Tous les systèmes</option>${systems.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Période</label><select id="rc101PortfolioPeriod"><option value="all">Toutes dates</option><option value="today">Aujourd’hui</option><option value="d30">30 jours</option><option value="m6">6 mois</option><option value="y1">1 an</option><option value="custom">Personnalisée</option></select></div><div class="field"><label>Du</label><input id="rc101PortfolioStart" type="date"></div><div class="field"><label>Au</label><input id="rc101PortfolioEnd" type="date"></div><div class="field"><label>Montant minimum</label><input id="rc101PortfolioMin" type="number" min="0"></div><div class="field"><label>Montant maximum</label><input id="rc101PortfolioMax" type="number" min="0"></div></div><div id="rc101PortfolioResults"></div>`}
function rc101RefreshPortfolio(){const clientId=$('rc101PortfolioClient')?.value||'',system=$('rc101PortfolioSystem')?.value||'',period=$('rc101PortfolioPeriod')?.value||'all',min=Number($('rc101PortfolioMin')?.value||0),max=Number($('rc101PortfolioMax')?.value||Infinity),[a,b]=rc101PeriodBounds(period,$('rc101PortfolioStart')?.value,$('rc101PortfolioEnd')?.value),rows=rcAllClients().map(c=>{const orders=(store.tenants[c.id]?.orders||[]).filter(o=>new Date(o.createdAt).getTime()>=a&&new Date(o.createdAt).getTime()<=b&&(!system||rc101OrderSystems(o).includes(system))),total=orders.reduce((n,o)=>n+Number(o.totalEUR||0),0),paid=orders.reduce((n,o)=>n+rcOrderPaid(o),0),balance=orders.reduce((n,o)=>n+rcOrderBalance(o),0);return{c,orders,total,paid,balance}}).filter(x=>(!clientId||x.c.id===clientId)&&x.total>=min&&x.total<=max).sort((a,b)=>b.total-a.total),total=rows.reduce((n,x)=>n+x.total,0),paid=rows.reduce((n,x)=>n+x.paid,0),balance=rows.reduce((n,x)=>n+x.balance,0);$('rc101PortfolioResults').innerHTML=`<div class="rc-v10-kpis">${rcKpi('Valeur filtrée',rcMoney(total),`${rows.length} client(s)`,'portfolio')}${rcKpi('Encaissé',rcMoney(paid),'Période filtrée','receivables')}${rcKpi('Solde',rcMoney(balance),'Reste dû','receivables')}${rcKpi('Commandes',rows.reduce((n,x)=>n+x.orders.length,0),'Résultat filtré','global-orders')}</div><div class="rc-v10-panel" style="margin-top:14px"><div class="table-wrap"><table class="rc-v10-table"><thead><tr><th>Client</th><th>Catégorie</th><th>Commandes</th><th>Total achats</th><th>Encaissé</th><th>Solde</th></tr></thead><tbody>${rows.map(x=>`<tr><td><button class="btn secondary small" data-rc-client-sheet="${x.c.id}">${esc(x.c.company)}</button></td><td>${rcTierFor(x.total)}</td><td>${x.orders.length}</td><td>${rcMoney(x.total)}</td><td>${rcMoney(x.paid)}</td><td>${rcMoney(x.balance)}</td></tr>`).join('')||'<tr><td colspan="6">Aucun résultat.</td></tr>'}</tbody></table></div></div>`;rcBindDynamic()}
function renderLoyaltyV10(){const t=rcThresholds(),clients=rcAllClients(),systems=[...new Set(rcAllOrders().map(x=>rcSystemKey(x.order)))].sort();return`<div class="rc-v10-hero"><h2>Fidélité & catégories clients</h2><p>Seuils administrables et classement automatique Standard, Premium, Prestige.</p></div><div class="rc-v10-panel"><h3>Seuils administrables</h3><div class="form-grid"><div class="field span2"><label>Premium à partir de</label><input id="rcPremiumThreshold" type="number" value="${t.premium}"></div><div class="field span2"><label>Prestige à partir de</label><input id="rcPrestigeThreshold" type="number" value="${t.prestige}"></div><div class="field span2"><label>&nbsp;</label><button class="btn primary" id="rcSaveThresholds">Enregistrer</button></div></div></div><div class="rc101-filter" style="margin-top:14px"><div class="field"><label>Nom / société</label><input id="rc101LoyaltySearch"></div><div class="field"><label>Système acheté</label><select id="rc101LoyaltySystem"><option value="">Tous les systèmes</option>${systems.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Montant minimum</label><input id="rc101LoyaltyMin" type="number" min="0"></div><div class="field"><label>Montant maximum</label><input id="rc101LoyaltyMax" type="number" min="0"></div><div class="field"><label>Catégorie</label><select id="rc101LoyaltyTier"><option value="">Toutes</option><option>Standard</option><option>Premium</option><option>Prestige</option></select></div></div><div class="rc-v10-client-grid" style="margin-top:14px">${clients.map(rcClientCard).join('')}</div>`}
function rc101FilterClientCards(prefix){const q=($(prefix+'Search')?.value||'').toLowerCase(),system=($(prefix+'System')?.value||'').toLowerCase(),min=Number($(prefix+'Min')?.value||0),max=Number($(prefix+'Max')?.value||Infinity),tier=$(prefix+'Tier')?.value||'';document.querySelectorAll('[data-rc-client]').forEach(c=>c.style.display=(!q||c.dataset.search.includes(q))&&(!system||c.dataset.systems.includes(system))&&Number(c.dataset.amount)>=min&&Number(c.dataset.amount)<=max&&(!tier||c.dataset.tier===tier)?'':'none')}

const rc101BaseAdminMessages=renderAdminMessagesV9;
renderAdminMessagesV9=function(){const clients=rcAllClients(),tabs=`<div class="rc101-message-tabs"><button class="btn secondary small ${rc101MessageMode==='active'?'active':''}" data-rc101-message-mode="active">Messages actifs</button><button class="btn secondary small ${rc101MessageMode==='archived'?'active':''}" data-rc101-message-mode="archived">Messages archivés</button><button class="btn secondary small ${rc101MessageMode==='deleted'?'active':''}" data-rc101-message-mode="deleted">Messages supprimés</button></div>`;if(rc101MessageMode==='deleted'){const deleted=clients.flatMap(c=>(store.tenants[c.id]?.messages||[]).filter(m=>m.deletedByAdmin).map(m=>({c,m}))).sort((a,b)=>new Date(b.m.createdAt)-new Date(a.m.createdAt));return`<div class="premium-hero-v96"><h2>Messagerie professionnelle</h2><p>Consultez et restaurez les messages supprimés.</p>${tabs}</div><div class="premium-panel-v96 rc101-deleted-list">${deleted.map(x=>`<article class="rc101-deleted"><b>${esc(x.c.company)} · ${esc(rcClientName(x.c))}</b><div>${esc(x.m.text)}</div><small>${new Date(x.m.createdAt).toLocaleString('fr-FR')}</small><button class="btn secondary small" data-rc101-restore-message="${x.c.id}|${x.m.id}">Restaurer</button></article>`).join('')||'<div class="empty">Aucun message supprimé.</div>'}</div>`}const html=rc101BaseAdminMessages();setTimeout(()=>{if(rc101MessageMode==='archived'&&$('messageArchiveV96')){$('messageArchiveV96').value='archived';$('messageArchiveV96').dispatchEvent(new Event('change'))}},0);return html.replace('</div><div class="premium-filter-v96">',tabs+'</div><div class="premium-filter-v96">')};

function renderSystemLibraryV10(){return`<div class="rc-v10-hero"><h2>Bibliothèque des systèmes</h2><p>Les ${SYSTEMS.length} systèmes disponibles dans l’interface client sont centralisés ici. L’administrateur peut modifier les étapes et la photo.</p></div><div class="rc-v10-note"><b>Validation technique obligatoire.</b> Toute modification des couches influence le calculateur. Vérifiez les fiches techniques avant publication.</div><div class="rc-v10-system-grid" style="margin-top:14px">${SYSTEMS.map(sys=>{const meta=rc101SystemMeta(sys.id);return`<article class="rc-v10-system"><div>${rc101SystemImageHTML(sys.id,sys.name)}</div><div class="rc-v10-system-body"><h3>${esc(sys.name)}</h3><div class="rc101-step-list">${meta.layers.map((x,i)=>`<div class="rc101-step"><span class="n">${i+1}</span><span>${esc(x)}</span></div>`).join('')}</div><div class="toolbar"><button class="btn primary small" data-rc-use-system="${sys.id}">Utiliser dans le calculateur</button><button class="btn secondary small" data-rc101-edit-system="${sys.id}">Modifier étapes / photo</button></div></div></article>`}).join('')}</div>`}
function rc101CompressImage(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=reject;r.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const max=1600,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.82))};img.src=r.result};r.readAsDataURL(file)})}
function rc101EditSystem(id){const sys=SYSTEMS.find(s=>s.id===id),meta=rc101SystemMeta(id);if(!sys)return;showModal(`<h3>${esc(sys.name)}</h3><p>Modifiez l’ordre, ajoutez ou supprimez des étapes. La photo est limitée à 5 Mo et optimisée avant enregistrement.</p><div id="rc101EditSteps" class="rc101-step-list">${meta.layers.map((x,i)=>`<div class="rc101-step" data-rc101-edit-step><span class="n">${i+1}</span><input value="${esc(x)}"><button class="btn danger small" data-rc101-remove-step>Supprimer</button></div>`).join('')}</div><div class="toolbar"><button class="btn secondary" id="rc101AddStep">Ajouter une étape</button></div><div class="field"><label>Photo / schéma du système</label><input id="rc101SystemPhoto" type="file" accept="image/*"></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Annuler</button><button class="btn primary" id="rc101SaveSystem">Enregistrer</button></div>`);const renumber=()=>document.querySelectorAll('[data-rc101-edit-step] .n').forEach((n,i)=>n.textContent=i+1),bindRemove=()=>document.querySelectorAll('[data-rc101-remove-step]').forEach(b=>b.onclick=()=>{b.closest('[data-rc101-edit-step]').remove();renumber()});bindRemove();$('rc101AddStep').onclick=()=>{$('rc101EditSteps').insertAdjacentHTML('beforeend',`<div class="rc101-step" data-rc101-edit-step><span class="n">0</span><input value="Nouvelle étape"><button class="btn danger small" data-rc101-remove-step>Supprimer</button></div>`);renumber();bindRemove()};$('rc101SaveSystem').onclick=async()=>{const layers=[...document.querySelectorAll('[data-rc101-edit-step] input')].map(x=>x.value.trim()).filter(Boolean);if(!layers.length)return toast('Le système doit conserver au moins une étape.');meta.layers=layers;const file=$('rc101SystemPhoto').files[0];if(file){if(file.size>5*1024*1024)return toast('La photo dépasse 5 Mo.');meta.image=await rc101CompressImage(file)}rc101ApplySystemLayers();auditV9('Modification bibliothèque système','système:'+id,null,{steps:layers.length,photo:!!file});saveStore();closeModal();renderShell();toast('Système mis à jour.')}};

const rc101BaseCalculator=renderCalculator;
function rc101MultiRows(){const t=tenantData();t.multiCalculator=Array.isArray(t.multiCalculator)?t.multiCalculator:[];return t.multiCalculator}
function rc101RenderMulti(){const max=Math.max(1,Number(rc101Settings().maxCalculatorSystems)||10),rows=rc101MultiRows();return`<section class="rc-v10-panel rc101-multi"><h3>Calcul multi-systèmes</h3><p>Le calcul par système reste recommandé. Vous pouvez toutefois ajouter jusqu’à <b>${max}</b> systèmes dans un seul projet et une seule commande.</p><div id="rc101MultiRows">${rows.map((r,i)=>`<div class="rc101-multi-row" data-rc101-multi-row="${i}"><div class="field"><label>Système ${i+2}</label><select data-rc101-multi-system>${SYSTEMS.map(s=>`<option value="${s.id}" ${s.id===r.systemId?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Surface m²</label><input data-rc101-multi-area type="number" min="0" step=".01" value="${Number(r.areaM2||form.areaM2)}"></div><button class="btn danger" data-rc101-remove-multi="${i}">Supprimer</button></div>`).join('')}</div><div class="toolbar"><button class="btn secondary" id="rc101AddSystem">Ajouter un système</button><button class="btn primary" id="rc101CalculateAll">Calculer tous les systèmes</button><label style="margin-left:auto">Maximum administrateur <input id="rc101MaxSystems" type="number" min="1" max="10" value="${max}" style="width:72px" ${isAdmin()?'':'disabled'}></label></div>${rc101AdditionalResults.length?`<div class="rc101-multi-results">${rc101AdditionalResults.map(r=>`<article class="rc101-multi-result">${rc101SystemImageHTML(r.system.id,r.system.name)}<h4>${esc(r.system.name)}</h4><div>${num.format(r.areaM2)} m² · ${r.lines.length-r.summary.missing}/${r.lines.length} lignes calculées</div><div class="amount">${eur.format(r.summary.totalEUR)}</div></article>`).join('')}</div><div class="toolbar"><button class="btn primary" id="rc101AddAllCart">Ajouter tous les systèmes à une commande</button><button class="btn dark" onclick="window.print()">PDF client multi-systèmes</button></div>`:''}</section>`}
renderCalculator=function(){if(!result)calculate();return rc101BaseCalculator()+`<section class="rc-v10-panel" style="margin:14px 0"><h3>Photo des couches — ${esc(result.system.name)}</h3>${rc101SystemImageHTML(result.system.id,result.system.name)}</section>`+rc101RenderMulti()};
function rc101CalculateAdditional(){const saved={...form},savedResult=result,rows=rc101MultiRows();rc101AdditionalResults=[];for(const row of rows){form.systemId=row.systemId;form.areaM2=Number(row.areaM2)||0;form.areaSqft=form.areaM2*SQFT_PER_M2;result=null;calculate();rc101AdditionalResults.push(JSON.parse(JSON.stringify(result)))}Object.assign(form,saved);result=savedResult;if(!result)calculate();renderShell()}
function rc101AddResultToCart(r){const t=tenantData();for(const l of r.lines)for(const p of l.pack.rows){const key=r.system.id+'|'+l.productName+'|'+p.label,ex=t.cart.find(x=>x.key===key);if(ex){ex.quantity+=p.quantity;ex.totalEUR=round2(ex.quantity*ex.unitPriceEUR);ex.totalUSD=round2(ex.quantity*ex.unitPriceUSD)}else t.cart.push({key,product:l.productName,pack:p.label,quantity:p.quantity,unitPriceEUR:p.unitPriceEUR,unitPriceUSD:p.unitPriceUSD,totalEUR:p.subtotalEUR,totalUSD:p.subtotalUSD,systemId:r.system.id,systemName:r.system.name,systemImage:rc101SystemImage(r.system.id),systemAreaM2:r.areaM2})}}
function rc101AddAllToCart(){if(!result)calculate();rc101AddResultToCart(result);rc101AdditionalResults.forEach(rc101AddResultToCart);saveStore();toast('Tous les systèmes ont été regroupés, séparés par système.');go('cart')}
const rc101BaseCreateOrder=createOrderFromCartV96;
createOrderFromCartV96=function(mode='later'){const cart=JSON.parse(JSON.stringify(tenantData()?.cart||[])),order=rc101BaseCreateOrder(mode);if(!order)return order;const groups={};for(const item of cart){const id=item.systemId||order.systemId;groups[id]=groups[id]||{systemId:id,systemName:item.systemName||SYSTEMS.find(s=>s.id===id)?.name||'Système',image:item.systemImage||rc101SystemImage(id),totalEUR:0,items:0,areaM2:item.systemAreaM2||0};groups[id].totalEUR+=Number(item.totalEUR||0);groups[id].items++}order.systemGroups=Object.values(groups);order.systemName=order.systemGroups.map(x=>x.systemName).join(' + ');order.calculatorPdfSnapshot={createdAt:new Date().toISOString(),project:order.project,systems:order.systemGroups};saveStore();return order};
function rc101OrderSnapshotHTML(order){const groups=order.systemGroups||[{systemId:order.systemId,systemName:order.systemName,image:rc101SystemImage(order.systemId),totalEUR:order.totalEUR,items:(order.items||[]).length}];return`<section class="rc-v10-panel" style="margin-top:14px"><h3>PDF et photos des systèmes reçus</h3><div class="rc101-multi-results">${groups.map(g=>`<article class="rc101-multi-result">${g.image?`<img src="${esc(g.image)}" alt="${esc(g.systemName)}">`:rc101SystemImageHTML(g.systemId,g.systemName)}<h4>${esc(g.systemName)}</h4><div>${g.items||0} produit(s)</div><div class="amount">${rcMoney(g.totalEUR)}</div></article>`).join('')}</div><button class="btn dark" onclick="window.print()">Ouvrir / enregistrer le PDF reçu</button></section>`}
const rc101BaseOrderDetail=orderDetailV96;orderDetailV96=(order,admin=false,tenantId='',orderIndex=-1)=>rc101BaseOrderDetail(order,admin,tenantId,orderIndex)+rc101OrderSnapshotHTML(order);
const rc101BaseShowOrderDetail=rcShowOrderDetail;rcShowOrderDetail=function(tid,index){rc101BaseShowOrderDetail(tid,index);const o=store.tenants[tid]?.orders?.[index];if(o&&$('modalCard'))$('modalCard').insertAdjacentHTML('beforeend',rc101OrderSnapshotHTML(o))};

renderOrders=function(){const t=tenantData(),orders=t.orders||[],systems=[...new Set(orders.flatMap(rc101OrderSystems))].sort(),total=orders.reduce((n,o)=>n+Number(o.totalEUR||0),0),unique=[...new Set(orders.flatMap(rc101OrderSystems))];return`<div class="premium-hero-v96"><h2>Mes commandes</h2><p>Suivez la vérification, le paiement et la disponibilité au dépôt. Une commande transmise est verrouillée ; toute correction passe par une demande de modification.</p><div class="alert-summary-v96"><span>${orders.length} commande(s)</span><span>${eur.format(total)} commandé(s)</span></div><div class="rc101-system-badges">${unique.map(x=>`<span>${esc(x)}</span>`).join('')||'<span>Aucun système acheté</span>'}</div></div>${orderLegendV96()}<div class="rc101-filter"><div class="field"><label>Recherche</label><input id="rc101OrderSearch" placeholder="N°, projet, système"></div><div class="field"><label>Statut</label><select id="rc101OrderStatus"><option value="">Tous</option>${RC101_ORDER_STATUSES.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Paiement</label><select id="rc101OrderPayment"><option value="">Tous</option>${RC101_PAYMENT_STATUSES.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Système</label><select id="rc101OrderSystem"><option value="">Tous</option>${systems.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Montant minimum</label><input id="rc101OrderMin" type="number" min="0"></div><div class="field"><label>Montant maximum</label><input id="rc101OrderMax" type="number" min="0"></div><div class="field"><label>Période</label><select id="rc101OrderPeriod"><option value="all">Toutes dates</option><option value="today">Aujourd’hui</option><option value="d30">30 jours</option><option value="m6">6 mois</option><option value="y1">1 an</option><option value="custom">Personnalisée</option></select></div><div class="field"><label>Du</label><input id="rc101OrderStart" type="date"></div><div class="field"><label>Au</label><input id="rc101OrderEnd" type="date"></div></div><div class="order-cards-v96">${orders.map((o,i)=>`<div data-rc101-client-order data-search="${esc((o.id+' '+o.project+' '+rc101OrderSystems(o).join(' ')).toLowerCase())}" data-status="${esc(o.status)}" data-payment="${esc(o.paymentStatus)}" data-systems="${esc(rc101OrderSystems(o).join('|'))}" data-amount="${Number(o.totalEUR||0)}" data-time="${new Date(o.createdAt).getTime()}">${orderCardV96(o,i,currentClient(),false,'')}</div>`).join('')||'<div class="card panel empty">Aucune commande.</div>'}</div>`}
function rc101FilterOrdersClient(){const q=($('rc101OrderSearch')?.value||'').toLowerCase(),status=$('rc101OrderStatus')?.value||'',payment=$('rc101OrderPayment')?.value||'',system=$('rc101OrderSystem')?.value||'',min=Number($('rc101OrderMin')?.value||0),max=Number($('rc101OrderMax')?.value||Infinity),[a,b]=rc101PeriodBounds($('rc101OrderPeriod')?.value||'all',$('rc101OrderStart')?.value,$('rc101OrderEnd')?.value);document.querySelectorAll('[data-rc101-client-order]').forEach(x=>x.style.display=(!q||x.dataset.search.includes(q))&&(!status||x.dataset.status===status)&&(!payment||x.dataset.payment===payment)&&(!system||x.dataset.systems.split('|').includes(system))&&Number(x.dataset.amount)>=min&&Number(x.dataset.amount)<=max&&Number(x.dataset.time)>=a&&Number(x.dataset.time)<=b?'':'none')}
renderSimulations=function(){const t=tenantData(),sims=t.simulations||[],systems=[...new Set(sims.flatMap(s=>s.bundleSystems?.map(x=>x.system.name)||[s.system?.name]).filter(Boolean))].sort();return`<div class="hero"><div><h2>Mes simulations enregistrées</h2><p><b>${sims.length}</b> simulation(s) enregistrée(s), classées par système, produit, montant et date.</p></div><button class="btn primary" onclick="go('calculator')">Nouvelle simulation</button></div><div class="rc101-filter"><div class="field"><label>Recherche</label><input id="rc101SimSearch" placeholder="Projet, système, produit"></div><div class="field"><label>Système</label><select id="rc101SimSystem"><option value="">Tous</option>${systems.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Montant minimum</label><input id="rc101SimMin" type="number" min="0"></div><div class="field"><label>Montant maximum</label><input id="rc101SimMax" type="number" min="0"></div><div class="field"><label>Période</label><select id="rc101SimPeriod"><option value="all">Toutes dates</option><option value="d30">30 jours</option><option value="m6">6 mois</option><option value="y1">1 an</option><option value="custom">Personnalisée</option></select></div><div class="field"><label>Du</label><input id="rc101SimStart" type="date"></div><div class="field"><label>Au</label><input id="rc101SimEnd" type="date"></div></div><div class="card panel"><div class="simulation-list-v92">${sims.map((s,i)=>{const bundle=s.bundleSystems||[s],names=bundle.map(x=>x.system.name),products=bundle.flatMap(x=>x.lines?.map(l=>l.productName)||[]),amount=s.bundleTotalEUR??s.summary.totalEUR;return`<article data-rc101-sim data-search="${esc((s.project+' '+names.join(' ')+' '+products.join(' ')).toLowerCase())}" data-systems="${esc(names.join('|'))}" data-amount="${amount}" data-time="${new Date(s.createdAt||Date.now()).getTime()}"><div><small>SIMULATION ${String(i+1).padStart(2,'0')}</small><h3>${esc(names.join(' + '))}</h3><p>${num.format(s.areaM2||bundle[0].areaM2)} m² · ${esc(s.project||'Projet sans nom')} · ${new Date(s.createdAt||Date.now()).toLocaleDateString('fr-FR')}</p></div><strong>${eur.format(amount)}</strong><div class="toolbar"><button class="btn secondary small" data-visual-sim="${i}">Visualiser</button><button class="btn primary small" data-load-sim="${i}">Rouvrir</button></div></article>`}).join('')||'<div class="empty">Aucune simulation enregistrée.</div>'}</div></div>`}
function rc101FilterSimulations(){const q=($('rc101SimSearch')?.value||'').toLowerCase(),system=$('rc101SimSystem')?.value||'',min=Number($('rc101SimMin')?.value||0),max=Number($('rc101SimMax')?.value||Infinity),[a,b]=rc101PeriodBounds($('rc101SimPeriod')?.value||'all',$('rc101SimStart')?.value,$('rc101SimEnd')?.value);document.querySelectorAll('[data-rc101-sim]').forEach(x=>x.style.display=(!q||x.dataset.search.includes(q))&&(!system||x.dataset.systems.split('|').includes(system))&&Number(x.dataset.amount)>=min&&Number(x.dataset.amount)<=max&&Number(x.dataset.time)>=a&&Number(x.dataset.time)<=b?'':'none')}

