 if(currentView==='orders'){['rc101OrderSearch','rc101OrderStatus','rc101OrderPayment','rc101OrderSystem','rc101OrderMin','rc101OrderMax','rc101OrderPeriod','rc101OrderStart','rc101OrderEnd'].forEach(id=>$(id)?.addEventListener(id.includes('Search')||id.includes('Min')||id.includes('Max')?'input':'change',rc101FilterOrdersClient));document.querySelectorAll('[data-order-detail-v96]').forEach(b=>b.onclick=()=>{const[,idx]=b.dataset.orderDetailV96.split('|'),o=tenantData().orders[Number(idx)];if(o)showModal(orderDetailV96(o,false,'',Number(idx)))})}
