let rc102TopLimit=5;

function rc102TopClientsHTML(clients){
  const visible=clients.slice(0,rc102TopLimit),max=Math.max(1,...visible.map(x=>x.s.net)),portfolioTotal=Math.max(1,clients.reduce((n,x)=>n+x.s.net,0));
  return `<section class="rc-v10-panel rc102-top-panel"><div class="rc102-section-head"><div><span class="eyebrow">TOP CLIENTS</span><h3>Clients ayant le plus acheté</h3><p>Classement calculé sur les achats nets, après remboursements.</p></div><div class="rc102-top-switch" role="group" aria-label="Nombre de clients affichés"><button class="${rc102TopLimit===5?'active':''}" data-rc102-top-limit="5">Top 5</button><button class="${rc102TopLimit===10?'active':''}" data-rc102-top-limit="10">Top 10</button></div></div><div class="rc102-top-chart">${visible.map((x,i)=>`<button class="rc102-top-row" data-rc102-top-client="${x.c.id}" title="Ouvrir la fiche de ${esc(x.c.company||rcClientName(x.c))}"><span class="rc102-top-rank">${i+1}</span><span class="rc102-top-name"><b>${esc(x.c.company||'Sans société')}</b><small>${esc(rcClientName(x.c))} · ${x.s.orders.length} commande(s)</small></span><span class="rc102-top-bar"><i style="width:${Math.max(3,x.s.net/max*100)}%"></i></span><span class="rc102-top-amount"><b>${rcMoney(x.s.net)}</b><small>${(x.s.net/portfolioTotal*100).toLocaleString('fr-FR',{maximumFractionDigits:1})}% du portefeuille</small></span></button>`).join('')||'<div class="rc-v10-empty">Aucun achat enregistré.</div>'}</div></section>`;
}

